 123	    /// Accumulate one wdata chunk carrying data for meta.mime (which
 124	    /// must be non-empty; an empty mime is a commit, not data).
 125	    ///
 126	    /// Returns error.TooLarge when the transaction exceeds max_size
 127	    /// and error.Invalid when the payload stream is not valid base64.
 128	    /// The caller must fail the whole transaction with EFBIG or EINVAL
 129	    /// respectively and abort it, as required by the protocol.
 130	    pub fn data(
 131	        self: *WriteState,
 132	        alloc: Allocator,
 133	        meta: *const Metadata,
 134	        payload: []const u8,
 135	    ) error{ OutOfMemory, TooLarge, Invalid }!void {
 136	        assert(meta.op == .wdata);
 137	        assert(meta.mime.len > 0);
 138	        // Switch the receiving entry if this chunk is for a different
 139	        // MIME type than the last one.
 140	        entry: {
 141	            if (self.current) |idx| {
 142	                const entry = &self.entries.items[idx];
 143	                if (std.mem.eql(u8, entry.mime, meta.mime)) {
 144	                    break :entry;
 145	                }
 146	
 147	                // Finalize the previous region. Its concatenated
 148	                // stream must have ended on a complete base64 group,
 149	                // otherwise the data was not correctly padded.
 150	                try self.finishCurrent();
 151	                entry.len = self.spool.items.len - entry.start;
 152	            }
 153	
 154	            // Re-using an earlier MIME type starts a fresh region,
 155	            // overwriting the previous mapping.
 156	            for (self.entries.items, 0..) |*entry, idx| {
 157	                if (std.mem.eql(u8, entry.mime, meta.mime)) {
 158	                    entry.start = self.spool.items.len;
 159	                    entry.len = 0;
 160	                    self.current = idx;
 161	                    break :entry;
 162	                }
 163	            }
 164	
 165	            if (self.entries.items.len >= max_write_mimes) {
 166	                log.warn(
 167	                    "clipboard write has too many MIME types, ignoring mime={s}",
 168	                    .{meta.mime},
 169	                );
 170	                self.current = null;
 171	                return;
 172	            }
 173	
 174	            try self.entries.append(alloc, .{
 175	                .mime = try self.arena.allocator().dupe(u8, meta.mime),
 176	                .start = self.spool.items.len,
 177	            });
 178	            self.current = self.entries.items.len - 1;
 179	        }
 180	
 181	        // The payloads for one MIME region concatenate into a single
 182	        // strict base64 stream, decoded directly into the spool's
 183	        // unused capacity. Invalid data aborts the transaction; per
 184	        // the spec it must not be silently discarded "since that
 185	        // turns corrupted data into apparently valid data".
 186	        try self.spool.ensureUnusedCapacity(alloc, self.decoder.maxLen(payload));
 187	        const decoded = self.decoder.feed(
 188	            payload,
 189	            self.spool.unusedCapacitySlice(),
 190	        ) catch return error.Invalid;
 191	
 192	        // The limit covers all decoded data in the transaction. Going
 193	        // over it aborts the entire write; partial clipboard contents
 194	        // must never reach the embedder.
 195	        const remaining = self.max_size -| self.spool.items.len;
 196	        if (decoded.len > remaining) return error.TooLarge;
 197	        self.spool.items.len += decoded.len;
 198	    }
