 200	    /// Finish the decode stream of the entry currently receiving
 201	    /// data. Returns error.Invalid when the stream ends mid-group,
 202	    /// i.e. the concatenated payload was not correctly padded.
 203	    fn finishCurrent(self: *WriteState) error{Invalid}!void {
 204	        self.decoder.finish() catch return error.Invalid;
 205	    }
