 207	    /// Register aliases from a walias packet: meta.mime is the target
 208	    /// (the type that carries data) and the payload is a base64-encoded,
 209	    /// whitespace-separated list of aliases. Returns error.Invalid for
 210	    /// an undecodable payload, which aborts the transaction with EINVAL.
 211	    pub fn alias(
 212	        self: *WriteState,
 213	        alloc: Allocator,
 214	        meta: *const Metadata,
 215	        payload: []const u8,
 216	    ) error{ OutOfMemory, Invalid }!void {
 217	        assert(meta.op == .walias);
 218	        assert(meta.mime.len > 0);
 219	        const decoded = try Payload.init(alloc, payload);
 220	        defer decoded.deinit(alloc);
 221	        if (!decoded.isValidUtf8()) return error.Invalid;
 222	        var it = decoded.mimeIterator();
 223	
 224	        // Associate the aliases
 225	        while (it.next()) |name| {
 226	            if (name.len > max_mime_len) continue;
 227	
 228	            // A repeated alias overwrites its previous target.
 229	            for (self.aliases.items) |*a| {
 230	                if (std.mem.eql(u8, a.alias, name)) {
 231	                    a.setTarget(meta.mime);
 232	                    break;
 233	                }
 234	            } else {
 235	                if (self.aliases.items.len >= max_write_aliases) {
 236	                    log.warn("clipboard write has too many aliases, ignoring", .{});
 237	                    return;
 238	                }
 239	
 240	                var a: Alias = .{
 241	                    .alias = try self.arena.allocator().dupe(u8, name),
 242	                };
 243	                a.setTarget(meta.mime);
 244	                try self.aliases.append(alloc, a);
 245	            }
 246	        }
 247	    }
