 249	    /// The result of a committed transaction. All slices borrow the
 250	    /// WriteState's memory and are valid until it is deinited.
 251	    pub const Committed = struct {
 252	        loc: clipboard.Location,
 253	        id: []const u8,
 254	        pw: []const u8,
 255	        name: []const u8,
 256	        contents: []const Content,
 257	
 258	        pub fn deinit(self: *const Committed, alloc: Allocator) void {
 259	            alloc.free(self.contents);
 260	        }
 261	    };
