 263	    /// Commit the transaction (a wdata packet without a MIME type).
 264	    /// The caller must use the result, call Committed.deinit, and then
 265	    /// deinit this state. Returns error.Invalid when the last region's
 266	    /// concatenated payload was not correctly padded; the caller must
 267	    /// fail the transaction with EINVAL and abort it.
 268	    pub fn commit(
 269	        self: *WriteState,
 270	        alloc: Allocator,
 271	    ) error{ OutOfMemory, Invalid }!Committed {
 272	        // Finalize the region receiving data.
 273	        if (self.current) |idx| {
 274	            try self.finishCurrent();
 275	            const entry = &self.entries.items[idx];
 276	            entry.len = self.spool.items.len - entry.start;
 277	            self.current = null;
 278	        }
 279	
 280	        // Resolve the final MIME map: entries in arrival order, then
 281	        // aliases applied sequentially against the evolving map so
 282	        // chained aliases work like kitty's dict iteration. An alias
 283	        // whose target has no mapping is dropped; an alias colliding
 284	        // with an existing name overwrites it.
 285	        var contents: std.ArrayList(Content) = .empty;
 286	        defer contents.deinit(alloc);
 287	        try contents.ensureTotalCapacity(
 288	            alloc,
 289	            self.entries.items.len + self.aliases.items.len,
 290	        );
 291	
 292	        for (self.entries.items) |*entry| {
 293	            contents.appendAssumeCapacity(.{
 294	                .mime = entry.mime,
 295	                .data = self.spool.items[entry.start..][0..entry.len],
 296	            });
 297	        }
 298	
 299	        for (self.aliases.items) |*a| {
 300	            const target: Content = target: {
 301	                for (contents.items) |c| {
 302	                    if (std.mem.eql(u8, c.mime, a.target())) {
 303	                        break :target c;
 304	                    }
 305	                }
 306	                continue;
 307	            };
 308	
 309	            for (contents.items) |*c| {
 310	                if (std.mem.eql(u8, c.mime, a.alias)) {
 311	                    c.data = target.data;
 312	                    break;
 313	                }
 314	            } else {
 315	                contents.appendAssumeCapacity(.{
 316	                    .mime = a.alias,
 317	                    .data = target.data,
 318	                });
 319	            }
 320	        }
 321	
 322	        return .{
 323	            .loc = self.loc,
 324	            .id = self.id,
 325	            .pw = self.pw,
 326	            .name = self.name,
 327	            .contents = try contents.toOwnedSlice(alloc),
 328	        };
 329	    }
 330	};
