  36	    /// Record a grant for pw. An existing grant for the same password
  37	    /// gains the new direction.
  38	    pub fn grant(
  39	        self: *Grants,
  40	        alloc: Allocator,
  41	        pw: []const u8,
  42	        dir: Direction,
  43	        one_time: bool,
  44	    ) Allocator.Error!void {
  45	        if (pw.len == 0 or pw.len > max_pw_len) return;
  46	
  47	        const entry: *Entry = entry: {
  48	            if (self.findIndex(pw)) |idx| {
  49	                const entry = &self.entries.items[idx];
  50	                entry.one_time = entry.one_time and one_time;
  51	                break :entry entry;
  52	            }
  53	
  54	            // Evict the oldest grant once full.
  55	            if (self.entries.items.len >= max_entries) {
  56	                const oldest = self.entries.orderedRemove(0);
  57	                alloc.free(oldest.pw);
  58	            }
  59	
  60	            const owned = try alloc.dupe(u8, pw);
  61	            errdefer alloc.free(owned);
  62	            try self.entries.append(alloc, .{
  63	                .pw = owned,
  64	                .one_time = one_time,
  65	            });
  66	            break :entry &self.entries.items[self.entries.items.len - 1];
  67	        };
