  75	    /// Check whether pw grants the given direction. A one-time grant is
  76	    /// consumed by this check even when the direction doesn't match,
  77	    /// matching kitty's pop-on-check behavior.
  78	    pub fn use(
  79	        self: *Grants,
  80	        alloc: Allocator,
  81	        pw: []const u8,
  82	        dir: Direction,
  83	    ) bool {
  84	        if (pw.len == 0) return false;
  85	        const idx = self.findIndex(pw) orelse return false;
  86	        const entry = &self.entries.items[idx];
  87	        const allowed = switch (dir) {
  88	            .read => entry.read,
  89	            .write => entry.write,
  90	        };
  91	        if (entry.one_time) {
  92	            const removed = self.entries.swapRemove(idx);
  93	            alloc.free(removed.pw);
  94	        }
  95	        return allowed;
  96	    }
  97	
  98	    fn findIndex(self: *const Grants, pw: []const u8) ?usize {
  99	        for (self.entries.items, 0..) |*entry, idx| {
 100	            if (std.mem.eql(u8, entry.pw, pw)) return idx;
 101	        }
 102	        return null;
 103	    }
