   134	    const cap = if (parser.capture) |*c| c else {
   135	        parser.state = .invalid;
   136	        return null;
   137	    };
   138	
   139	    const data = cap.trailing();
   140	
   141	    const metadata: []const u8, const payload: ?[]const u8 = result: {
   142	        const start = std.mem.indexOfScalar(u8, data, ';') orelse break :result .{ data, null };
   143	        break :result .{ data[0..start], data[start + 1 .. data.len] };
   144	    };
