   146	    parser.command = .{
   147	        .kitty_clipboard_protocol = .{
   148	            .metadata = metadata,
   149	            .payload = payload,
   150	            .terminator = .init(terminator_ch),
   151	        },
   152	    };
   153	
   154	    return &parser.command;
